"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-tooltip";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
export type TooltipProps = React.ComponentProps<typeof Primitive.Root>;
export function Tooltip(props: TooltipProps) {
  return <Primitive.Root delayDuration={220} {...props} />;
}
export type TooltipProviderProps = React.ComponentProps<
  typeof Primitive.Provider
>;
export function TooltipProvider(props: TooltipProviderProps) {
  return <Primitive.Provider delayDuration={220} {...props} />;
}
export type TooltipTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function TooltipTrigger(props: TooltipTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="tooltip-trigger"
      data-part="trigger"
      {...props}
    />
  );
}
export type TooltipPortalProps = React.ComponentProps<typeof Primitive.Portal>;
export function TooltipPortal(props: TooltipPortalProps) {
  return <Primitive.Portal {...props} />;
}
export const tooltipContentVariants = cva(
  "v-tip -show bg-[var(--v-ink)] text-[color:var(--v-on-ink)] text-xs leading-[1.3] py-1.5 px-2.5 rounded-[var(--r-sm)] max-w-[260px] z-[var(--z-tooltip)]",
);
export type TooltipContentProps = React.ComponentProps<
  typeof Primitive.Content
> & { portal?: boolean; appearance?: "callout" | "shortcut" | "annotation" };
function TooltipPaint() {
  const ref = useMorph<HTMLSpanElement>("surfaces");
  return (
    <span
      ref={ref}
      className="v-tooltip-paint"
      data-morph="both"
      data-r="css"
      aria-hidden="true"
    />
  );
}
export function TooltipContent({
  className,
  ref,
  children,
  sideOffset = 8,
  portal = true,
  appearance,
  ...props
}: TooltipContentProps) {
  const flowRef = useFlowAppearance<HTMLDivElement>(true, ref, "grow");
  const content = (
    <Primitive.Content
      ref={flowRef}
      data-slot="tooltip-content"
      data-part="content"
      data-appearance={appearance}
      sideOffset={sideOffset}
      className={cn(tooltipContentVariants(), className)}
      {...props}
    >
      {appearance && !props.asChild && <TooltipPaint />}
      {children}
    </Primitive.Content>
  );
  return portal ? <Primitive.Portal>{content}</Primitive.Portal> : content;
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-tip:where([data-slot="tooltip"], [data-slot^="tooltip-"]) {
  z-index: var(--z-tooltip);
  background: var(--v-ink);
  color: var(--v-on-ink);
  font-size: 12px;
  line-height: 1.3;
  padding: 6px 10px;
  border-radius: var(--r-sm);
  pointer-events: auto;
  opacity: 0;
  transition: opacity var(--t-micro);
  max-width: min(260px, calc(100vw - 24px));
  overflow-wrap: anywhere;
}
.v-tip:where([data-slot="tooltip"], [data-slot^="tooltip-"]).-show {
  opacity: 1;
}
.v-tip[data-appearance] {
  --mfill: var(--v-ink);
  --mstroke: var(--v-ink);
  border-radius: 8px;
  padding: 10px 13px;
  box-shadow: var(--shadow-float);
}
.v-tip[data-appearance]:has(> .v-tooltip-paint > svg.v-morph) {
  background: transparent;
}
.v-tip[data-appearance] {
  isolation: isolate;
}
.v-tooltip-paint {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: -1;
}
.v-tip[data-appearance="shortcut"] {
  display: flex;
  align-items: center;
  gap: 18px;
  border-radius: 10px;
}
.v-tip[data-appearance="shortcut"] kbd {
  border: 1px solid color-mix(in oklab, currentColor 35%, transparent);
  border-bottom-width: 3px;
  border-radius: 5px;
  padding: 4px 6px;
  font-family: inherit;
  white-space: nowrap;
}
.v-tip[data-appearance="annotation"] {
  --mfill: var(--v-paper);
  --mstroke: var(--v-border);
  color: var(--v-text);
  border-radius: 3px 12px 12px 3px;
  padding: 12px 15px;
  font-size: 12px;
  line-height: 1.55;
}
.v-tip[data-appearance="annotation"] strong {
  display: block;
  font-size: 11px;
  color: var(--v-text-3);
  margin-bottom: 3px;
}
.v-tip[data-appearance="annotation"]::before {
  content: "";
  position: absolute;
  width: 3px;
  top: 8px;
  bottom: 8px;
  left: 0;
  background: var(--v-pink);
  border-radius: 3px;
  pointer-events: none;
}
.v-tip[data-appearance="callout"]::after {
  content: "";
  position: absolute;
  background: var(--v-ink);
  pointer-events: none;
}
.v-tip[data-appearance="callout"][data-side="top"]::after {
  top: 100%;
  left: 50%;
  width: 1px;
  height: 6px;
}
.v-tip[data-appearance="callout"][data-side="bottom"]::after {
  bottom: 100%;
  left: 50%;
  width: 1px;
  height: 6px;
}
.v-tip[data-appearance="callout"][data-side="left"]::after {
  left: 100%;
  top: 50%;
  height: 1px;
  width: 6px;
}
.v-tip[data-appearance="callout"][data-side="right"]::after {
  right: 100%;
  top: 50%;
  height: 1px;
  width: 6px;
}
.v-tooltip-example {
  display: grid;
  gap: 20px;
  width: 100%;
  max-width: 580px;
  margin-inline: auto;
  padding: 22px;
  border-left: 2px solid var(--v-edge);
  color: var(--v-text);
}
.v-tooltip-example__label {
  color: var(--v-text-3);
  font-size: 11px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.v-tooltip-example h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 26px;
  line-height: 1.25;
}
.v-tooltip-example p {
  margin: 0;
  line-height: 1.6;
  max-width: 42ch;
}
.v-tooltip-example__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}
.v-tooltip-example [data-slot="tooltip-trigger"] {
  min-height: 44px;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="tooltip"],
  [data-slot^="tooltip-"],
  [data-slot="tooltip"]::before,
  [data-slot="tooltip"]::after,
  [data-slot^="tooltip-"]::before,
  [data-slot^="tooltip-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

}
